//! Executable examples for consumers: generated by the real loop.
//! Deliberate update: CALIPSO_UPDATE_EXAMPLES=1 cargo test -p scene-core --test contract_examples.
#![allow(clippy::disallowed_methods, clippy::disallowed_types)]
mod equivalence;
mod script;

use scene_core::contract::v4;
use scene_core::contract::*;
use scene_core::geom::{Quad, Rect};
use scene_core::look::Spent;
use scene_core::map::SiteMap;
use scene_core::policy::Policy;
use scene_core::{Input, Monitor};
use std::path::PathBuf;

fn envelope<T>(
    schema: SchemaId,
    seq: u64,
    at: SampleRef,
    body: T,
    last_event_seq: Option<u64>,
) -> Envelope<T> {
    Envelope {
        schema,
        seq,
        observed_at: at,
        body,
        last_event_seq,
        source: source(),
        profile: profile(),
        published_at_ms: 0,
        timing: (schema == SchemaId::SceneV3).then_some(Timing {
            wait_ms: 0.0,
            processing_ms: 0.0,
        }),
        event_id: (schema == SchemaId::EventsV3).then(|| format!("example-{seq}")),
    }
}

fn source() -> Source {
    Source {
        site: "example".into(),
        camera: "room".into(),
        run_id: "example".into(),
        build: Build {
            version: "0.1.0".into(),
            git: "example".into(),
        },
    }
}

fn profile() -> Profile {
    Profile {
        camera: Some(LayerRef {
            id: "room".into(),
            version: 1,
        }),
        resident: None,
        hash: ProfileHash("example".into()),
        senses: Vec::new(),
    }
}

/// The v4 envelope: the same, with v4's `SchemaId` and its own numbering.
fn envelope_v4<T>(
    schema: v4::SchemaId,
    seq: u64,
    at: SampleRef,
    body: T,
    last_event_seq: Option<u64>,
) -> v4::Envelope<T> {
    v4::Envelope {
        schema,
        seq,
        observed_at: at,
        body,
        last_event_seq,
        source: source(),
        profile: profile(),
        published_at_ms: 0,
        timing: (schema == v4::SchemaId::SceneV4).then_some(Timing {
            wait_ms: 0.0,
            processing_ms: 0.0,
        }),
        event_id: (schema == v4::SchemaId::EventsV4).then(|| format!("example-v4-{seq}")),
    }
}

/// The validator of a published schema (rule 13): the examples are validated
/// against the snapshot, not against the types that generated them.
fn validator(name: &str) -> jsonschema::Validator {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../contract/schema")
        .join(format!("{name}.json"));
    let schema: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    jsonschema::validator_for(&schema).unwrap()
}

fn assert_valid(validator: &jsonschema::Validator, line: &str) {
    let value: serde_json::Value = serde_json::from_str(line).unwrap();
    let errors: Vec<String> = validator
        .iter_errors(&value)
        .map(|e| format!("{} at {}", e, e.instance_path))
        .collect();
    assert!(errors.is_empty(), "{errors:#?}\n{line}");
}

fn snapshot(name: &str, content: &str) {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../contract/examples")
        .join(name);
    if std::env::var_os("CALIPSO_UPDATE_EXAMPLES").is_some() {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, content).unwrap();
    } else {
        assert_eq!(
            std::fs::read_to_string(path).unwrap(),
            content,
            "example {name} changed: regenerate on purpose"
        );
    }
}

#[test]
fn examples_s1_to_s8_are_reproducible() {
    let scene_schema = validator("calipso.scene.v3");
    let events_schema = validator("calipso.events.v3");
    for n in 1..=8 {
        let mut policy = Policy::default();
        policy.persistence.dwell_secs = 2.0;
        let mut monitor = Monitor::new(
            policy,
            SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0))),
        );
        let mut scenes = String::new();
        let mut events = String::new();
        let mut event_seq = 0;
        let mut final_scene = None;
        for (seq, (sequence, script)) in script::episode(n).into_iter().enumerate() {
            let at = SampleRef {
                session: SessionId(1),
                sequence: u64::from(sequence),
                source_secs: SourceSecs(f64::from(sequence)),
            };
            let out = monitor
                .handle(Input::Sample {
                    at,
                    frame: FrameInfo {
                        width: 640,
                        height: 480,
                    },
                })
                .drive(|request| (script.respond(&request.probe), Spent(1.0)));
            equivalence::check(&out);
            for event in out.events {
                assert_eq!(
                    event.after.occupants,
                    event.after.bed_seen + event.after.bed_held + event.after.floor_seen
                );
                event_seq += 1;
                let message = envelope(SchemaId::EventsV3, event_seq, event.at, event, None);
                let line = serde_json::to_string(&message).unwrap();
                assert_valid(&events_schema, &line);
                assert_eq!(
                    serde_json::from_str::<Envelope<Event>>(&line).unwrap(),
                    message
                );
                events.push_str(&line);
                events.push('\n');
            }
            let message = envelope(
                SchemaId::SceneV3,
                seq as u64 + 1,
                at,
                out.scene.as_ref().clone(),
                Some(event_seq),
            );
            let line = serde_json::to_string(&message).unwrap();
            assert_valid(&scene_schema, &line);
            assert_eq!(
                serde_json::from_str::<Envelope<Scene>>(&line).unwrap(),
                message
            );
            scenes.push_str(&line);
            scenes.push('\n');
            final_scene = Some(message.body);
        }
        let scene = final_scene.unwrap();
        let (bed, occupants) = match n {
            1 | 2 | 4 => (BedState::Held, 1),
            3 | 6 => (BedState::Empty, 0),
            5 => (BedState::Seen, 2),
            7 => (BedState::Held, 3),
            8 => (BedState::Held, 2),
            _ => unreachable!(),
        };
        assert_eq!(
            (scene.bed.state, scene.room.occupants),
            (bed, occupants),
            "S{n}"
        );
        // Two simultaneous entries carry different intermediate states.
        if n == 1 {
            let entered: Vec<_> = events
                .lines()
                .map(|line| serde_json::from_str::<Envelope<Event>>(line).unwrap())
                .filter(|e| e.body.body == EventBody::Entered)
                .collect();
            assert_eq!(
                (
                    entered[0].body.after.occupants,
                    entered[1].body.after.occupants
                ),
                (1, 2)
            );
        }
        snapshot(&format!("s{n}.scene.jsonl"), &scenes);
        snapshot(&format!("s{n}.events.jsonl"), &events);
    }
}

/// The S1–S8 examples in v4 (spec 1301): the same nights, from the same loop,
/// validated against the v4 schema. Each transition links its turn's scene
/// (`room.last_cell`).
#[test]
fn v4_examples_s1_to_s8_are_reproducible() {
    let scene_schema = validator("calipso.scene.v4");
    let events_schema = validator("calipso.events.v4");
    for n in 1..=8 {
        let mut policy = Policy::default();
        policy.persistence.dwell_secs = 2.0;
        let mut monitor = Monitor::new(
            policy,
            SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0))),
        );
        let (mut scenes, mut events, mut event_seq) = (String::new(), String::new(), 0);
        let mut transitions = 0;
        for (seq, (sequence, script)) in script::episode(n).into_iter().enumerate() {
            let out = observe(&mut monitor, u64::from(sequence), &script);
            for event in &out.v4.events {
                if let v4::Event::Transition(t) = event {
                    transitions += 1;
                    assert_eq!(out.v4.scene.room.last_cell.as_ref(), Some(&t.cell), "S{n}");
                }
                event_seq += 1;
                let at = match event {
                    v4::Event::Transition(t) => t.at,
                    v4::Event::Derived(d) => d.at,
                    v4::Event::Sensor(s) => s.at,
                    v4::Event::Map(m) => m.at,
                };
                let message =
                    envelope_v4(v4::SchemaId::EventsV4, event_seq, at, event.clone(), None);
                let line = serde_json::to_string(&message).unwrap();
                assert_valid(&events_schema, &line);
                assert_eq!(
                    serde_json::from_str::<v4::Envelope<v4::Event>>(&line).unwrap(),
                    message
                );
                events.push_str(&line);
                events.push('\n');
            }
            let message = envelope_v4(
                v4::SchemaId::SceneV4,
                seq as u64 + 1,
                out.at,
                out.v4.scene.as_ref().clone(),
                Some(event_seq),
            );
            let line = serde_json::to_string(&message).unwrap();
            assert_valid(&scene_schema, &line);
            assert_eq!(
                serde_json::from_str::<v4::Envelope<v4::Scene>>(&line).unwrap(),
                message
            );
            scenes.push_str(&line);
            scenes.push('\n');
        }
        assert!(transitions > 0, "S{n}: the night has transitions");
        snapshot(&format!("s{n}.scene.v4.jsonl"), &scenes);
        snapshot(&format!("s{n}.events.v4.jsonl"), &events);
    }
}

fn observe(monitor: &mut Monitor, sequence: u64, script: &script::Script) -> scene_core::Output {
    let output = monitor
        .handle(Input::Sample {
            at: SampleRef {
                session: SessionId(1),
                sequence,
                source_secs: SourceSecs(sequence as f64),
            },
            frame: FrameInfo {
                width: 640,
                height: 480,
            },
        })
        .drive(|request| (script.respond(&request.probe), Spent(1.0)));
    equivalence::check(&output);
    output
}

#[test]
fn a_failed_detector_neither_publishes_a_zero_nor_erases_the_belief() {
    use scene_core::look::Failure;
    let mut monitor = Monitor::new(
        Policy::default(),
        SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0))),
    );
    let seen = script::Script::bodies(vec![golden::world::in_bed(0)]);
    for n in 1..=3 {
        observe(&mut monitor, n, &seen);
    }
    let failed = script::Script {
        detect: Err(Failure::Model),
        ..Default::default()
    };
    let out = observe(&mut monitor, 4, &failed);
    assert_eq!(out.scene.evidence.bodies.status, BodiesStatus::Unavailable);
    assert!(out.scene.evidence.bodies.items.is_empty());
    assert_eq!(
        (out.scene.bed.state, out.scene.room.occupants),
        (BedState::Seen, 1)
    );
    assert!(out.events.is_empty());
    let at = SampleRef {
        session: SessionId(1),
        sequence: 5,
        source_secs: SourceSecs(5.0),
    };
    let out = monitor
        .handle(Input::Sensor {
            at,
            state: SensorState::Reconnecting,
        })
        .cancel();
    assert_eq!(out.events[0].after.occupants, 1);
    assert_eq!(
        out.scene.frame,
        Some(FrameInfo {
            width: 640,
            height: 480
        })
    );
    assert_eq!(out.scene.evidence.bodies.status, BodiesStatus::Unavailable);
    assert!(out.scene.republished.is_some());
}

#[test]
fn without_geometry_boxes_are_published_with_an_unknown_zone() {
    let mut map = SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0)));
    map.resolution = Some(FrameInfo {
        width: 1920,
        height: 1080,
    });
    let mut monitor = Monitor::new(Policy::default(), map);
    let out = observe(
        &mut monitor,
        1,
        &script::Script::bodies(vec![golden::world::in_bed(0)]),
    );
    assert_eq!(out.scene.evidence.bodies.status, BodiesStatus::Unzoned);
    let body = &out.scene.evidence.bodies.items[0];
    assert_eq!(body.zone, None);
    assert_eq!(body.bbox, golden::world::in_bed(0).bbox);
    assert_eq!(out.scene.bed.state, BedState::Unknown);
    assert_eq!(out.scene.room.occupants, 0);
}

#[test]
fn faces_say_whether_they_are_on_the_current_subject() {
    use scene_core::look::{Detection, Label};
    use scene_core::policy::FacePolicy;
    let mut policy = Policy::default();
    policy.persistence.dwell_secs = 0.0;
    policy.faces = Some(FacePolicy {
        min_confidence: 0.5,
    });
    let mut monitor = Monitor::new(
        policy,
        SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0))),
    );
    let face = Detection {
        bbox: Rect::new(170.0, 170.0, 190.0, 190.0),
        confidence: 0.9,
        label: Label::Person,
    };
    let seen = script::Script {
        detect: Ok(vec![golden::world::in_bed(0)]),
        faces: Ok(vec![face]),
        ..Default::default()
    };
    let out = observe(&mut monitor, 1, &seen);
    assert_eq!(out.scene.evidence.faces.status, FacesStatus::Ok);
    assert!(out.scene.evidence.faces.items[0].on_subject);
    let empty = script::Script::bodies(vec![golden::world::in_bed(0)]);
    let out = observe(&mut monitor, 2, &empty);
    assert_eq!(out.scene.evidence.faces.status, FacesStatus::Empty);
    assert!(out.scene.evidence.faces.items.is_empty());
}

#[test]
fn calibration_publishes_its_sample_and_the_map_before_the_first_frame() {
    use scene_core::policy::CalibrationPolicy;
    let policy = Policy {
        calibration: Some(CalibrationPolicy { retry_secs: 1.0 }),
        ..Default::default()
    };
    let mut map = SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0)));
    map.headboard = Some(Rect::new(100.0, 100.0, 500.0, 150.0));
    let mut monitor = Monitor::new(policy, map.clone());
    let at = SampleRef {
        session: SessionId(1),
        sequence: 0,
        source_secs: SourceSecs(0.0),
    };
    let before = monitor
        .handle(Input::Sensor {
            at,
            state: SensorState::Streaming,
        })
        .cancel();
    assert_eq!(before.scene.frame, None);
    assert_eq!(before.scene.map.bed, map.bed);
    assert_eq!(before.scene.map.headboard, map.headboard);
    let out = observe(&mut monitor, 1, &script::Script::default());
    assert_eq!(
        out.scene.map.calibration,
        Calibration::Complete {
            reference_m: 2.0,
            since: Some(out.at)
        }
    );
    assert!(
        out.events
            .iter()
            .any(|e| e.body == EventBody::BedCalibrated { reference_m: 2.0 })
    );
}

#[test]
fn the_published_examples_validate_and_the_invalid_fixture_does_not() {
    let scene_schema = validator("calipso.scene.v3");
    let events_schema = validator("calipso.events.v3");
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../contract");
    for n in 1..=8 {
        for (kind, v) in [("scene", &scene_schema), ("events", &events_schema)] {
            let text =
                std::fs::read_to_string(dir.join(format!("examples/s{n}.{kind}.jsonl"))).unwrap();
            for line in text.lines() {
                assert_valid(v, line);
            }
        }
    }
    let invalid: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(dir.join("fixtures/scene-invalid.json")).unwrap(),
    )
    .unwrap();
    assert!(
        !scene_schema.is_valid(&invalid),
        "the contract guardian accepted an invalid message"
    );
}

#[test]
fn a_still_pose_keeps_its_origin_and_a_failure_forgets_the_reference() {
    use scene_core::look::Failure;
    use scene_core::policy::EnrichPolicy;
    let mut policy = Policy::default();
    policy.persistence.dwell_secs = 0.0;
    policy.enrich = Some(EnrichPolicy {
        move_threshold: 0.1,
        depth: true,
        min_keypoint_score: 0.3,
        posture_tolerance: 0.05,
        max_pose_age_secs: None,
    });
    let mut monitor = Monitor::new(
        policy,
        SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0))),
    );
    let seen = script::Script::bodies(vec![golden::world::in_bed(0)]);
    let first = observe(&mut monitor, 1, &seen);
    let subject = first.scene.subject.as_ref().unwrap();
    assert_eq!(
        subject.pose.as_ref().unwrap().provenance,
        Provenance::Current
    );
    assert_eq!(
        subject.depth.as_ref().unwrap().provenance,
        Provenance::Current
    );

    let still = observe(&mut monitor, 2, &seen);
    assert_eq!(
        still
            .scene
            .attention
            .looks
            .iter()
            .map(|look| look.kind)
            .collect::<Vec<_>>(),
        vec![LookKind::Detect, LookKind::Pose]
    );
    assert_eq!(
        still.scene.attention.looks[1].outcome,
        LookOutcome::Skipped {
            reason: SkipReason::SubjectStill
        }
    );
    let subject = still.scene.subject.as_ref().unwrap();
    assert_eq!(
        subject.pose.as_ref().unwrap().provenance,
        Provenance::Stable { since: first.at }
    );
    assert_eq!(
        subject.depth.as_ref().unwrap().provenance,
        Provenance::Stable { since: first.at }
    );

    let failed = script::Script {
        detect: Ok(vec![golden::world::in_bed(1)]),
        pose: Err(Failure::Model),
        ..Default::default()
    };
    let failed_output = observe(&mut monitor, 3, &failed);
    let subject = failed_output.scene.subject.as_ref().unwrap();
    assert!(subject.pose.is_none() && subject.depth.is_none());
    assert!(
        failed_output
            .scene
            .attention
            .looks
            .iter()
            .any(|look| look.kind == LookKind::Depth
                && look.outcome
                    == LookOutcome::Skipped {
                        reason: SkipReason::NoPose
                    })
    );

    let recovered = observe(
        &mut monitor,
        4,
        &script::Script::bodies(vec![golden::world::in_bed(1)]),
    );
    assert_eq!(
        recovered
            .scene
            .attention
            .looks
            .iter()
            .map(|look| look.kind)
            .collect::<Vec<_>>(),
        vec![LookKind::Detect, LookKind::Pose, LookKind::Depth]
    );
    assert_eq!(
        recovered
            .scene
            .subject
            .as_ref()
            .unwrap()
            .pose
            .as_ref()
            .unwrap()
            .provenance,
        Provenance::Current
    );
}

#[test]
fn the_initial_map_keeps_the_reference_and_the_retry_delay() {
    use scene_core::policy::CalibrationPolicy;
    let policy = Policy {
        calibration: Some(CalibrationPolicy { retry_secs: 2.0 }),
        ..Default::default()
    };
    let at = SampleRef {
        session: SessionId(1),
        sequence: 7,
        source_secs: SourceSecs(7.0),
    };
    let mut map = SiteMap::new(Quad::from_rect(Rect::new(100.0, 100.0, 500.0, 400.0)));
    map.calibration_attempt = Some(at);
    let mut monitor = Monitor::new(policy.clone(), map.clone());
    let waiting = observe(&mut monitor, 8, &script::Script::default());
    assert_eq!(
        waiting.scene.attention.looks[1].outcome,
        LookOutcome::Skipped {
            reason: SkipReason::RetryWait
        }
    );
    assert_eq!(waiting.scene.map.calibration, Calibration::Unavailable);
    assert!(waiting.events.is_empty());
    let learned = observe(&mut monitor, 9, &script::Script::default());
    assert_eq!(
        learned.scene.map.calibration,
        Calibration::Complete {
            reference_m: 2.0,
            since: Some(learned.at)
        }
    );
    assert_eq!(
        learned.events,
        vec![Event::domain(
            learned.at,
            Cause::MapLearned,
            EventBody::BedCalibrated { reference_m: 2.0 },
            After {
                room: RoomState::Empty,
                occupants: 0,
                bed: BedState::Empty,
                bed_seen: 0,
                bed_held: 0,
                floor_seen: 0,
            }
        )]
    );

    map.bed_reference = Some(1.5);
    let mut monitor = Monitor::new(policy, map);
    let seeded = observe(&mut monitor, 8, &script::Script::default());
    assert_eq!(
        seeded.scene.map.calibration,
        Calibration::Complete {
            reference_m: 1.5,
            since: None
        }
    );
    assert_eq!(seeded.scene.attention.looks.len(), 1);
    assert!(seeded.events.is_empty());
}
